insert into public.skill_definitions
  (id, name, description, kind, hidden, conditions, effect, locks, owner_limit, evolves_from, excludes, uses_per_battle, rumor, enabled)
values
  ('silent_finish', 'Silent Finish', 'A first hit on an unaware enemy deals 3x damage. If it kills, you stay hidden, and each stealth kill in a row adds +1x, up to 10x. Monsters only. Needs a dagger in hand.', 'passive', true, '{"counter":"one_hit_kills","op":">=","value":1000}'::jsonb, '{"weapons":["daggers"],"passive":{"silent_finish":{"mult":3,"chain_max":10,"hide_s":3}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('phantom_legion', 'Phantom Legion', 'Every perfect dodge leaves a shadow clone that fights for 5 seconds (up to 5 at once, each dealing 30% of your damage).', 'passive', true, '{"counter":"phantom_fights","op":">=","value":100}'::jsonb, '{"passive":{"phantom_legion":{"pct":0.3,"life_s":5,"max":5}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('thousand_needles', 'Thousand Needles', 'Dagger crits stack bleeding. At 10 stacks, a normal monster dies instantly, and a boss loses 5% of its max HP. Needs a dagger in hand.', 'passive', true, '{"counter":"crits_daggers","op":">=","value":10000}'::jsonb, '{"weapons":["daggers"],"passive":{"thousand_needles":{"stacks":10,"boss_pct":0.05,"tick_pct":0.01}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('shadow_walk', 'Shadow Walk', 'Go fully invisible for 5 seconds, and appear behind the nearest enemy you can see. 10 minute cooldown.', 'active', true, '{"counter":"escapes","op":">=","value":300}'::jsonb, '{"active":{"cooldown_s":600,"shadow_walk":{"invisible_s":5}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('phantom_verdict', 'Phantom Verdict', 'Ultimate, bosses only. Each boss attack you dodge charges the gauge. 50: 50% of the boss''s HP (once per fight, resets the gauge). 100: a full kill. 200: a full kill + 20% EXP. Fire or keep charging at each tier.', 'active', true, '{"counter":"boss_fight_dodges_best","op":">=","value":100}'::jsonb, '{"active":{"ultimate":{"gauge":"boss_dodges","tiers":[50,100,200]}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('armor_crusher', 'Armor Crusher', 'Each hammer hit lowers the target''s defense by 2%, stacking up to 50%. Needs a hammer in hand.', 'passive', true, '{"counter":"hits_hammer","op":">=","value":5000}'::jsonb, '{"weapons":["hammer"],"passive":{"armor_crusher":{"per_hit":0.02,"max":0.5}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('quake_slam', 'Quake Slam', 'Ground Slam sends out a shockwave that knocks down everything nearby.', 'passive', true, '{"counter":"skill_kills_ground_slam","op":">=","value":500}'::jsonb, '{"passive":{"quake_slam":{"stun_ms":1000,"reach":300}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('ringing_blow', 'Ringing Blow', 'Your stuns last 1 second longer, and stunned enemies take 30% more damage.', 'passive', true, '{"counter":"stuns_dealt","op":">=","value":1000}'::jsonb, '{"passive":{"ringing_blow":{"extra_ms":1000,"dmg_mult":1.3}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('full_swing', 'Full Swing', 'Charged swings can''t be interrupted and deal 3x damage.', 'passive', true, '{"counter":"full_swing_wins","op":">=","value":100}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('anvil_breaker', 'Anvil Breaker', 'Ultimate, bosses only. Each hammer hit on the boss charges the gauge. 50: 50% of the boss''s HP (once per fight, resets the gauge). 100: a full kill. 200: a full kill + 20% EXP. Needs a hammer in hand.', 'active', true, '{"counter":"boss_fight_hits_hammer_best","op":">=","value":200}'::jsonb, '{"weapons":["hammer"],"active":{"ultimate":{"gauge":"boss_weapon_hits","tiers":[50,100,200]}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('seven_strikes', 'Seven Strikes', 'The 7th hit of every combo deals 7x damage. Needs empty hands or a strength bracelet.', 'passive', true, '{"counter":"combos_7","op":">=","value":1000}'::jsonb, '{"weapons":["unarmed","strength_bracelet"],"passive":{"seven_strikes":{"every":7,"mult":7,"gap_ms":1000}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('breath_control', 'Breath Control', 'Slowly regenerate HP and MP during combat.', 'passive', true, '{"counter":"clean_fights","op":">=","value":100}'::jsonb, '{"passive":{"breath_control":{"hp_pct":0.01,"mp":1}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('empty_vessel', 'Empty Vessel', 'AGI and VIT bonus while unarmored.', 'passive', true, '{"counter":"unarmored_wins","op":">=","value":500}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('pressure_point', 'Pressure Point', 'Your hits can paralyze for 1 second.', 'passive', true, '{"counter":"weak_point_crits","op":">=","value":500}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('heavenly_palm', 'Heavenly Palm', 'Ultimate, bosses only. Each unarmed hit on the boss charges the gauge. 100: 50% of the boss''s HP (once per fight, resets the gauge). 200: a full kill. 400: a full kill + 20% EXP. Needs empty hands or a strength bracelet.', 'active', true, '{"counter":"boss_fight_hits_fists_best","op":">=","value":1000}'::jsonb, '{"weapons":["unarmed","strength_bracelet"],"active":{"ultimate":{"gauge":"boss_weapon_hits","tiers":[100,200,400]}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('quick_draw', 'Quick Draw', 'The first shot of every fight is a guaranteed crit. Needs a pistol in hand.', 'passive', true, '{"counter":"quick_draw_wins","op":">=","value":100}'::jsonb, '{"weapons":["pistol"],"passive":{"quick_draw":true}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('dead_mans_hand', 'Dead Man''s Hand', 'Below 10% HP: +50% fire rate (unlimited ammo too, once guns use ammo). Needs a pistol in hand.', 'passive', true, '{"counter":"low_hp_wins","op":">=","value":200}'::jsonb, '{"weapons":["pistol"],"passive":{"dead_mans_hand":{"below":0.1,"rate":1.5}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('final_round', 'Final Round', 'The last bullet of every reload deals double damage and pierces.', 'passive', true, '{"counter":"last_bullet_kills","op":">=","value":300}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('ricochet', 'Ricochet', 'Bullets bounce to a second target. Evolves to a third.', 'passive', true, '{"counter":"ricochet_hits","op":">=","value":1000}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('high_noon', 'High Noon', 'Ultimate, bosses only. Each bullet that hits the boss charges the gauge. 100: 50% of the boss''s HP (once per fight, resets the gauge). 200: a full kill. 400: a full kill + 20% EXP. Needs a pistol in hand.', 'active', true, '{"counter":"boss_fight_gun_dmg_best","op":">=","value":100000}'::jsonb, '{"weapons":["pistol"],"active":{"ultimate":{"gauge":"boss_weapon_hits","tiers":[100,200,400]}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('hawk_line', 'Hawk Line', 'Range +50%, and damage grows with distance. Needs a bow in hand.', 'passive', true, '{"counter":"max_range_hits","op":">=","value":10000}'::jsonb, '{"weapons":["bow"],"passive":{"hawk_line":{"range":1.5,"max_mult":1.5}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('marked_prey', 'Marked Prey', 'The last enemy you shot is marked: your arrows never miss it, and it can''t hide or turn invisible. Needs a bow in hand.', 'passive', true, '{"counter":"marked_runs","op":">=","value":50}'::jsonb, '{"weapons":["bow"],"passive":{"marked_prey":true}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('bending_shot', 'Bending Shot', 'Your arrows curve around walls and obstacles.', 'passive', true, '{"counter":"cover_hits","op":">=","value":500}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('last_arrow', 'Last Arrow', 'When you have 1 arrow left, it splits into 10.', 'passive', true, '{"counter":"last_arrow_wins","op":">=","value":50}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('heavens_draw', 'Heaven''s Draw', 'Ultimate, bosses only. Each weak-point hit on the boss charges the gauge. 25: 50% of the boss''s HP (once per fight, resets the gauge). 50: a full kill. 100: a full kill + 20% EXP.', 'active', true, '{"counter":"boss_weak_point_hits","op":">=","value":300}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false)
